    private static function workspaceNavigation(string $tab):void
    {
        $groups=[
            'overview'=>['Overview',['overview'=>['Today',null]]],
            'productions'=>['Productions & Performances',['performances'=>['Productions','inventory'],'schedule'=>['Calendar & scheduling','inventory'],'blocks'=>['Seat blocking','inventory']]],
            'boxoffice'=>['Box Office',['sales'=>['Sell tickets','sell'],'orders'=>['Orders & refunds','report'],'promotions'=>['Discounts & promo codes','configure'],'complimentary'=>['Complimentary tickets','complimentary'],'checkin'=>['Door check-in','checkin']]],
            'settings'=>['Settings',['venues'=>['Venues & spaces','venues'],'configure'=>['Configuration & access','configure']]]
        ];
        $active=match($tab){'performance_details'=>'overview','layout'=>'venues','performance','pricing','add_performance'=>'performances','tickets'=>'orders','checkout','select'=>'sales',default=>$tab};
        echo '<div class="commerce-workspace"><aside class="commerce-workspace-nav"><nav aria-label="Commerce workspace">';
        foreach($groups as $key=>[$label,$links]){
            $visible=array_filter($links,fn($item)=>!$item[1]||self::can($item[1]));if(!$visible)continue;
            $current=isset($links[$active]);$destination=array_key_first($visible);
            echo '<div class="commerce-nav-group"><a class="commerce-workspace-link" href="'.self::e(self::url($destination)).'" '.($current?'aria-current="true"':'').'>'.self::e($label).'</a>';
            if($current&&count($visible)>1){echo '<nav aria-label="'.self::e($label).' tools">';foreach($visible as $route=>[$name])echo '<a href="'.self::e(self::url($route)).'" '.($active===$route?'aria-current="page"':'').'>'.self::e($name).'</a>';echo '</nav>';}
            echo '</div>';
        }
        echo '</nav></aside><section class="commerce-content">';
    }
    private static function purchaseSteps(string $tab,?string $state=null):void
    {
        if($tab==='checkout'&&$state===null)return;
        $step=match($tab){'select'=>1,'checkout'=>2,'order'=>4,default=>0};
        if($tab==='checkout'){
            // Do not expose any order state until the normal checkout ownership check runs.
            $step=match($state){'paid'=>4,'payment_pending','exception','refund_pending'=>3,default=>2};
        }
        echo '<ol class="commerce-checkout-steps" aria-label="Ticket purchase progress">';
        foreach(['Choose production & performance','Seats & ticket types','Review & checkout','Payment confirmation','Receive tickets'] as $i=>$label)echo '<li '.($step===$i?'aria-current="step"':'').'>'.($i+1).'. '.self::e($label).'</li>';
        echo '</ol>';
    }
