ult pricing change','text','','required maxlength="500"');echo '<button>Save organization defaults</button></form>';}else echo '<p>Publish a seating layout before setting default ticket prices.</p>';}else echo '<p>Organization pricing requires migration 111.</p>';echo '</details>';if(!CommerceAccess::local())echo '<p>Hosted staff tools require explicit Commerce staff grants. The storefront_tester grant permits only restricted ticket preview for active adults, not staff operations.</p>';echo '<h3>Staff access</h3><p>Assign Commerce permissions without changing Connect roles. Only eligible adult accounts can receive access.</p>';echo '<div class="commerce-panel"><h4>Find an eligible account</h4><p>Search by name or email. Only active adult accounts appear; selecting a person does not grant access until you submit the form.</p><form method="get"><input type="hidden" name="tab" value="configure">';self::input('person_q','Name or email','search',mb_substr(trim((string)($_GET['person_q']??'')),0,120),'maxlength="120"');echo '<button type="submit">Find account</button></form>';
        $personQuery=mb_substr(trim((string)($_GET['person_q']??'')),0,120);$eligible=[];
