    private static function orderedInventory(array $items,array $document):array
    {
        $sections=array_column($document['sections'],'order','key');$rows=array_column($document['rows'],'order','key');
        usort($items,static function($a,$b)use($sections,$rows){$a=json_decode($a['seat_json'],true);$b=json_decode($b['seat_json'],true);return [($sections[$a['section']]??0),($rows[$a['row']]??0),(float)$a['x'],(float)$a['y']]<=>[($sections[$b['section']]??0),($rows[$b['row']]??0),(float)$b['x'],(float)$b['y']]?:strnatcasecmp($a['label'],$b['label']);});return$items;
    }
    private static function money(int $minor,string $currency):string{return self::e($currency).' '.number_format($minor/100,2);}
    private static function storefront():void
    {
        echo '<div class="commerce-discovery-heading"><p class="commerce-eyebrow">CTSMD Connect Tickets</p><h1>Find your next show</h1><p>Choose a performance to see ticket options and select your seats.</p>';
        if(self::cartEnabled()||self::rebuiltCart())echo '<p><a class="button" href="'.self::e(self::url('cart')).'">View cart</a></p>';
        echo '</div>';
        $performances=CommerceStorefrontService::performances(self::$db,self::$user,self::$org,(int)($_GET['production']??0));
        if(!$performances){echo '<p>No upcoming performances are available right now.</p>';return;}
        $productions=[];
        foreach($performances as $p)$productions[$p['production_id']][]=$p;
        foreach($productions as $shows){
            $first=$shows[0];$prices=[];
            foreach($shows as $p)foreach(json_decode($p['prices_json'],true) as $categories)foreach($categories as $price)$prices[]=(int)$price;
            echo '<article class="commerce-showtimes"><div class="commerce-production-intro">';
            if($first['has_poster'])echo '<img class="commerce-artwork" alt="" src="'.self::e(self::$base.'/production-poster?id='.(int)$first['production_id']).'">';
            echo '<div class="commerce-show-overview"><p class="commerce-eyebrow">On stage</p><h2>'.self::e($first['title']).'</h2><p>'.self::e($first['venue']).'</p>';
            if($prices)echo '<p class="commerce-starting-price">Tickets from '.self::money(min($prices),$first['currency']).'</p>';
            echo '</div></div><h3 class="commerce-choose-heading">Choose a performance</h3><div class="commerce-performance-choices">';
            foreach($shows as $p){
                $items=CommerceInventoryService::availability(self::$db,self::$user,self::$org,(int)$p['id']);
                $available=count(array_filter($items,fn($i)=>in_array($i['state'],['available','released'],true)));
                $held=count(array_filter($items,fn($i)=>$i['state']==='held'));
                $closed=$p['sales_status']!=='open';
                $status=$closed?'Sales closed':($available===0?($held?'Currently unavailable':'Sold out'):$available.' '.($p['seating_mode']==='general_admission'?'tickets':'seats').' available');
                $date=new DateTimeImmutable($p['starts_at']);$dateText=$date->format('l, F j, Y');$time=$date->format('g:i A');
                echo '<div class="commerce-performance-choice"><div class="commerce-date-tile" aria-hidden="true"><span>'.$date->format('D').'</span><strong>'.$date->format('j').'</strong><span>'.$date->format('M').'</span></div>';
                echo '<div class="commerce-choice-details"><h4>'.self::e($time).'</h4><p>'.self::e($dateText).'</p><p class="commerce-choice-availability" role="status">'.self::e($status).'</p>';
                if($p['venue']!==$first['venue'])echo '<p>'.self::e($p['venue']).'</p>';
                echo '</div><div class="commerce-choice-action">';
                if(!$closed&&$available>0)echo '<a class="button" href="'.self::e(self::url('select',['performance'=>$p['id']])).'">Select tickets <span class="commerce-sr-only">for '.self::e($dateText.' at '.$time).'</span></a>';
                else echo '<span class="commerce-choice-disabled" aria-disabled="true">'.self::e($status).'</span>';
                echo '</div></div>';
            }
            echo '</div></article>';
        }
        echo '<p class="commerce-discovery-note">Applicable fees and taxes are shown before purchase. This is a restricted test environment; no live purchases are available.</p>';
    }
    private static function promotions():void
    {
        CommerceAccess::demand(self::$db,self::$user,self::$org,'configure');
        echo '<div class="commerce-heading"><h1>Discounts &amp; promo codes</h1></div><p>Create a code for all current and future productions, or restrict it to one production. Discounts apply to eligible ticket prices before tax, not fees. One code per cart. Expiration dates are interpreted in the CTSMD operating timezone.</p>';
        if(!CommercePromoService::available(self::$db)){echo '<p role="status">Promo codes require migration 121. No codes are active.</p>';return;}
        echo '<section class="commerce-promo-panel"><h2>Create promo code</h2>';self::form('promo_create');
        self::input('code','Code','text','','required minlength="3" maxlength="48" pattern="[A-Za-z0-9_-]{3,48}" autocomplete="off" placeholder="OPENINGNIGHT"');
        echo '<label>Applies to<select name="production"><option value="0">All current and future productions</option>';
        foreach(self::rows("SELECT id,title FROM productions WHERE lifecycle_stage IN ('upcoming','planning','in_production','performing') ORDER BY title") as $p)echo '<option value="'.(int)$p['id'].'">'.self::e($p['title']).'</option>';
        echo '</select></label><div class="commerce-finance-grid"><label>Discount type<select name="kind"><option value="amount">Fixed amount off eligible tickets</option><option value="percent">Percentage off eligible tickets</option></select></label>';
        self::input('value','Amount or percent','number','','required min="0.01" max="100000" step="0.01"');
        self::input('limit','Maximum redemptions (0 = unlimited)','number','1','required min="0" max="1000000" step="1"');
        echo '</div><details class="commerce-legacy-discount"><summary>Advanced restrictions · optional</summary><div class="commerce-finance-grid">';self::input('minimum_amount','Minimum eligible ticket subtotal','number','0.00','min="0" max="10000" step="0.01" required');self::input('per_customer_limit','Uses per customer (0 = unlimited)','number','0','min="0" max="1000000" step="1" required');self::input('max_discount_amount','Maximum discount for percentage codes','number','0.00','min="0" max="10000" step="0.01" required');echo '</div><p>These apply only to qualifying tickets, not fees or taxes. Per-customer limits use the signed-in CTSMD account. A zero discount cap means no cap.</p></details>';self::input('expires','Expires on ('.AppClock::label().')','date',(new DateTimeImmutable('+30 days',AppClock::timezone()))->format('Y-m-d'),'required min="'.AppClock::today().'"');
        echo '<button>Create code</button></form><p>Single use: set maximum redemptions to 1. For multi-use, choose a higher number or zero for unlimited. An unresolved payment reserves one use until it is safely resolved.</p></section>';
        $codes=self::rows("SELECT p.*,pr.title AS production_title,(SELECT COUNT(*) FROM commerce_promo_claims x WHERE x.promo_id=p.id AND x.organization_id=p.organization_id AND x.state='redeemed') redeemed,(SELECT COUNT(*) FROM commerce_promo_claims x WHERE x.promo_id=p.id AND x.organization_id=p.organization_id AND x.state='reserved') reserved FROM commerce_promo_codes p LEFT JOIN productions pr ON pr.id=p.production_id WHERE p.organization_id=? ORDER BY p.id DESC LIMIT 100",[self::$org]);
        echo '<section><h2>Existing codes</h2>';
        if(!$codes)echo '<p>No codes created yet.</p>';
        foreach($codes as $p){$value=$p['discount_kind']==='percent'?number_format((int)$p['discount_value']/100,2).'%':self::money((int)$p['discount_value'],CommerceStore::organization(self::$db,self::$org)['currency']);$active=(int)$p['enabled']&&$p['expires_at_utc']>=gmdate('Y-m-d H:i:s');
            echo '<article class="commerce-record"><strong>'.self::e($p['code']).'</strong><p>'.self::e($p['production_title']??'All productions').' · '.self::e($value).' · '.($active?'Enabled':'Inactive').'</p><p>'.(int)$p['redeemed'].' redeemed · '.(int)$p['reserved'].' awaiting payment · '.((int)$p['max_redemptions']===0?'Unlimited uses':(int)$p['max_redemptions'].' maximum uses').' · Expires '.self::e(AppClock::localDateTime((string)$p['expires_at_utc'],'M j, Y · g:i A T')).'</p><p>Minimum eligible subtotal: '.self::money((int)($p['minimum_subtotal_minor']??0),CommerceStore::organization(self::$db,self::$org)['currency']).' · Per customer: '.((int)($p['per_customer_limit']??0)===0?'Unlimited':(int)$p['per_customer_limit']).' · Discount cap: '.((int)($p['max_discount_minor']??0)===0?'None':self::money((int)$p['max_discount_minor'],CommerceStore::organization(self::$db,self::$org)['currency'])).'</p>';
            if((int)$p['enabled']){self::form('promo_disable',['id'=>(int)$p['id']]);echo '<button type="submit">Disable code</button></form>';}
            echo '</article>';
        }
        echo '</section>';
    }
    private static function cart():void
    {
        if(self::rebuiltCart()){self::rebuiltCartPage();return;}
        if(!self::cartEnabled())throw new RuntimeException('Cart preview is not available.');
        echo '<h1 class="commerce-task-title">Your cart</h1><p>Review reserved tickets across performances. Payment for multi-show carts is not enabled yet.</p>';
        try{$cart=self::cartCredentials();}catch(RuntimeException){echo '<p>Your cart is empty.</p><p><a class="button" href="'.self::e(self::url()).'">Browse performances</a></p>';return;}
        $summary=CommerceCartService::summary(self::$db,self::$user,self::$org,(int)$cart['id'],(string)$cart['token']);
        if(!$summary['orders']){echo '<p>Your cart is empty.</p><p><a class="button" href="'.self::e(self::url()).'">Browse performances</a></p>';return;}
        foreach($summary['orders'] as $order){
            $p=self::performanceContext((int)$order['performance_id']);
            $seconds=self::rows('SELECT GREATEST(0,TIMESTAMPDIFF(SECOND,NOW(),expires_at)) seconds FROM commerce_orders WHERE organization_id=? AND id=?',[self::$org,$order['id']]);
            $active=$order['state']==='held'&&(int)$seconds[0]['seconds']>0;
            $lines=self::rows('SELECT description,category,unit_minor FROM commerce_order_lines WHERE organization_id=? AND order_id=? ORDER BY id',[self::$org,$order['id']]);
            echo '<article class="commerce-cart-item"><h2>'.self::e($p['title']).'</h2><p>'.self::e(self::staffDate($p).' · '.$p['venue']).'</p>';
            echo '<p><strong>'.count($lines).' '.(count($lines)===1?'ticket':'tickets').'</strong> · '.($active?'Reserved for '.(int)ceil((int)$seconds[0]['seconds']/60).' more minutes':($order['state']==='held'?'Hold expired':self::e(self::staffStatus($order['state'])))).'</p>';
            echo '<ul class="commerce-cart-tickets">';
            foreach($lines as $line)echo '<li><span>'.self::e($line['description']).' · '.self::e($line['category']).'</span><strong>'.self::money((int)$line['unit_minor'],$order['currency']).'</strong></li>';
            echo '</ul><p class="commerce-cart-item-total">Performance total (including applicable fees and taxes): <strong>'.self::money((int)$order['total_minor'],$order['currency']).'</strong></p>';
            if($order['state']==='held'){self::form('cart_remove',['id'=>$order['id']]);echo '<button type="submit">'.($active?'Remove tickets':'Remove expired selection').'</button></form>';}
            echo '</article>';
        }
        $currency=(string)$summary['orders'][0]['currency'];
        echo '<section class="commerce-cart-summary" aria-label="Cart price breakdown"><h2>Order summary</h2><dl>';
        foreach(['subtotal_minor'=>'Tickets','discount_minor'=>'Discounts','tax_minor'=>'Taxes','fee_minor'=>'Fees'] as $field=>$label){
            $amount=(int)$summary['totals'][$field];
            if($amount===0)continue;
            echo '<div><dt>'.self::e($label).'</dt><dd>'.($field==='discount_minor'?'−':'').self::money($amount,$currency).'</dd></div>';
        }
        echo '<div class="commerce-cart-grand-total"><dt>Total</dt><dd>'.self::money((int)$summary['totals']['total_minor'],$currency).'</dd></div></dl></section>';
        try{
            $readiness=CommerceCartService::readiness(self::$db,self::$user,self::$org,(int)$cart['id'],(string)$cart['token']);
            echo '<p role="status">'.(int)$readiness['order_count'].' performance selections are held and ready for a future combined checkout. No payment is available yet.</p>';
        }catch(RuntimeException $e){echo '<p role="alert">'.self::e($e->getMessage()).'</p>';}
        echo '<p>Each selection includes its applicable fees and taxes. Unpaid holds expire automatically. Multi-show checkout remains disabled in this pilot.</p><p><a class="button" href="'.self::e(self::url()).'">Continue shopping</a></p>';
    }
    private static function rebuiltCartPage(bool $checkout=false):void
    {
        $summary=self::shoppingSummary();$cart=$summary['cart'];$items=$summary['items'];$active=(bool)$cart['active'];echo '<h1 class="commerce-task-title">'.($checkout?'Review your tickets':'Your cart').'</h1>';
        if(!$items){echo '<p>Your cart is empty.</p><p><a class="button" href="'.self::e(self::url()).'">Continue shopping</a></p>';if(!$checkout)self::recentPurchases();return;}
