        foreach($groups as $performance=>$tickets){$p=self::performanceContext((int)$performance);$subtotal=0;$validCount=0;echo '<article class="commerce-cart-item"><h2>'.self::e($p['title']).'</h2><p>'.self::e(self::staffDate($p).' · '.$p['venue']).'</p><ul class="commerce-cart-tickets">';
            if($p['seating_mode']==='general_admission'){
                $buckets=[];foreach($tickets as $item){$valid=$active&&$item['state']==='held';$key=json_encode([$item['category'],(int)$item['unit_minor'],$item['currency'],$valid],JSON_THROW_ON_ERROR);if(!isset($buckets[$key]))$buckets[$key]=['item'=>$item,'count'=>0,'valid'=>$valid];$buckets[$key]['count']++;if($valid){$validCount++;$subtotal+=(int)$item['unit_minor'];$currency??=$item['currency'];}}
                foreach($buckets as $bucket){$item=$bucket['item'];$count=$bucket['count'];$label=$count.' × '.$item['category'].' · General admission';echo '<li><span>'.self::e($label).($bucket['valid']?'':' · Expired').'</span><strong>'.self::money((int)$item['unit_minor']*$count,$item['currency']).'</strong>';self::form('shopping_remove',['id'=>$performance,'seat'=>$item['seat_key']]);echo '<button aria-label="'.self::e('Remove one '.$item['category'].' general admission ticket').'">'.($count>1?'Remove one':'Remove').'</button></form></li>';}
            }else foreach($tickets as $item){$valid=$active&&$item['state']==='held';$seat=json_decode($item['seat_json'],true,flags:JSON_THROW_ON_ERROR);$name=self::seatLabel($seat);echo '<li><span>'.self::e($name.' · '.$item['category']).($valid?'':' · Expired').'</span><strong>'.self::money((int)$item['unit_minor'],$item['currency']).'</strong>';if($valid)echo '<a href="'.self::e(self::url('select',['performance'=>$performance,'replace'=>CommerceShoppingCartService::itemReference($cart,$item)])).'">Change seat</a>';self::form('shopping_remove',['id'=>$performance,'seat'=>$item['seat_key']]);echo '<button aria-label="'.self::e('Remove '.$name).'">Remove</button></form></li>';if($valid){$validCount++;$subtotal+=(int)$item['unit_minor'];$currency??=$item['currency'];}}
            echo '</ul><p><a href="'.self::e(self::url('select',['performance'=>$performance])).'">Change seats or add tickets</a></p></article>';if($validCount>0){$discount=min($subtotal,(int)$p['discount_minor'])+(int)($promoQuote['allocations'][$performance]??0);$tax=intdiv(($subtotal-$discount)*(int)$p['tax_basis_points']+5000,10000);$fee=(int)$p['fee_minor'];$totals['subtotal_minor']+=$subtotal;$totals['discount_minor']+=$discount;$totals['tax_minor']+=$tax;$totals['fee_minor']+=$fee;$totals['total_minor']+=$subtotal-$discount+$tax+$fee;}}
        if($currency!==null){echo '<section class="commerce-cart-summary"><h2>Order summary</h2>';if($promoQuote['code'])echo '<p>Promo code '.self::e($promoQuote['code']).' applied to eligible tickets.</p>';echo '<dl>';foreach(['subtotal_minor'=>'Tickets','discount_minor'=>'Discounts','tax_minor'=>'Taxes','fee_minor'=>'Fees','total_minor'=>'Total'] as $key=>$label)echo '<div><dt>'.$label.'</dt><dd>'.($key==='discount_minor'?'−':'').self::money($totals[$key],$currency).'</dd></div>';echo '</dl></section>';
            if(!$checkout&&CommercePromoService::available(self::$db)){
                echo '<section class="commerce-promo-entry"><h3>Have a promo code?</h3>';self::form('shopping_promo');
