    private static function cartPayableTotal(array $summary):int
    {
        $cart=$summary['cart'];$groups=[];
        foreach($summary['items'] as $item){if(!$cart['active']||$item['state']!=='held')continue;$id=(int)$item['performance_id'];$groups[$id]['subtotal']=($groups[$id]['subtotal']??0)+(int)$item['unit_minor'];}
        if(!$groups)return -1;
        foreach($groups as $id=>&$g){$p=self::performanceContext((int)$id);$g['discount']=min($g['subtotal'],(int)$p['discount_minor']);$g['fee']=(int)$p['fee_minor'];$g['tax_basis_points']=(int)$p['tax_basis_points'];}unset($g);
        $quote=CommercePromoService::quote(self::$db,self::$org,(int)$cart['id'],$groups);
        $total=0;foreach($groups as $id=>$g){$discount=$g['discount']+(int)($quote['allocations'][$id]??0);$total+=$g['subtotal']-$discount+$g['fee']+intdiv(($g['subtotal']-$discount)*$g['tax_basis_points']+5000,10000);}return $total;
    }
    private static function shoppingCheckout():void
    {
        if(!self::rebuiltPayment())throw new RuntimeException('Checkout is unavailable.');$summary=self::shoppingSummary();$cart=$summary['cart'];$items=$summary['items'];$valid=(bool)$cart['active']&&$items&&count(array_filter($items,fn($i)=>$i['state']!=='held'))===0;self::rebuiltCartPage(true);if(!$valid)return;
        $free=CommercePromoService::selected(self::$db,self::$org,(int)$cart['id'])!==null&&self::cartPayableTotal($summary)===0;echo '<section><h2>Purchaser information</h2><p>Enter your details once for all tickets.</p>';self::form($free?'shopping_free_checkout':'shopping_checkout',['cart_id'=>$cart['id']]);self::input('customer_name','Full name','text',self::draft('customer_name',(string)(self::$user['name']??'')),'required maxlength="190" autocomplete="name"');self::input('customer_email','Email address','email',self::draft('customer_email',(string)(self::$user['email']??'')),'required maxlength="254" autocomplete="email"');self::input('customer_phone','Phone (optional)','tel',self::draft('customer_phone'),'maxlength="40" autocomplete="tel"');echo '<button>'.($free?'Complete free order':'Continue to secure payment').'</button></form><p>'.($free?'Your promo code covers the full total. No Stripe payment is required. Tickets will be issued after the reservation is verified.':'You will review and pay on Stripe’s secure test checkout.').'</p></section>';
    }
    private static function shoppingConfirmation():void
    {
        $reference=(string)($_GET['purchase']??'');$p=CommerceShoppingCheckoutService::forOwner(self::$db,self::$user,self::$org,$reference);
        if((int)$p['total_minor']>0&&in_array($p['state'],['prepared','pending','exception'],true)&&CommerceStripeProvider::configured())$p=CommerceShoppingCheckoutService::reconcile(self::$db,self::$org,(int)$p['id']);
        echo '<h1 class="commerce-task-title">'.($p['state']==='succeeded'?'Your tickets':'Your purchase').'</h1>';
        if($p['state']==='succeeded'){echo '<p>'.((int)$p['total_minor']===0&&$p['remote_session_id']===null?'Free order confirmed · ':'Payment confirmed · ').self::money((int)$p['total_minor'],$p['currency']).'</p><p>Purchaser: '.self::e($p['customer_name'].' · '.$p['customer_email']).'</p>';if(CommercePromoService::available(self::$db)){$redeemed=self::rows("SELECT c.code FROM commerce_promo_claims x JOIN commerce_promo_codes c ON c.id=x.promo_id AND c.organization_id=x.organization_id WHERE x.organization_id=? AND x.purchase_id=? AND x.state='redeemed'",[self::$org,$p['id']]);if($redeemed)echo '<p>Promo code: '.self::e($redeemed[0]['code']).'</p>';}foreach(CommerceShoppingCheckoutService::ticketsForOwner(self::$db,self::$user,self::$org,$reference) as $ticket){echo '<article class="commerce-ticket"><h2>'.self::e($ticket['title']).'</h2><p>'.self::e(self::staffDate($ticket['starts_at']).' · '.$ticket['venue']).'</p><p>'.self::e($ticket['description'].' · '.$ticket['category'].' · '.self::staffStatus($ticket['state'])).' · '.self::money((int)$ticket['unit_minor'],$p['currency']).'</p>';if($ticket['state']==='valid'&&$ticket['schedule_status']==='scheduled')echo CommerceReceiptService::qr($ticket['token']);elseif($ticket['schedule_status']!=='scheduled')echo '<p>Contact the box office about this performance.</p>';echo '</article>';}$totals=['subtotal'=>0,'discount'=>0,'tax'=>0,'fee'=>0];foreach(json_decode($p['snapshot_json'],true,flags:JSON_THROW_ON_ERROR) as $group)foreach(array_keys($totals) as $key)$totals[$key]+=(int)$group[$key];echo '<section><h2>Receipt</h2><dl class="commerce-totals">';foreach(['subtotal'=>'Tickets','discount'=>'Discounts','tax'=>'Taxes','fee'=>'Fees'] as $key=>$label)echo '<div><dt>'.$label.'</dt><dd>'.($key==='discount'?'−':'').self::money($totals[$key],$p['currency']).'</dd></div>';echo '<div class="commerce-total"><dt>Total</dt><dd>'.self::money((int)$p['total_minor'],$p['currency']).'</dd></div></dl></section><button type="button" onclick="window.print()">Print tickets / Save as PDF</button>';}
        elseif($p['state']==='canceled')echo '<p>Payment was canceled or expired. Your tickets were released.</p>';elseif($p['state']==='refund_pending'||($p['last_error']??'')==='external_refund_unconfirmed')echo '<p role="status">Your refund is being checked. Tickets cannot be used while the refund is pending.</p>';elseif($p['state']==='refunded')echo '<p>Your purchase was refunded and its tickets are no longer valid.</p>';
        else{if((int)$p['total_minor']===0&&$p['remote_session_id']===null){echo '<p role="status">Your complimentary purchase is ready to complete. No payment is required.</p>';self::form('shopping_free_recover',['purchase'=>$p['public_reference']]);echo '<button>Finish free order</button></form>';}else echo '<p role="status">Payment confirmation is still being checked. Your tickets remain protected. Reload this page to check again.</p>';
            if(Auth::hasRole(self::$user,'administrator')){
                $stage=empty($p['remote_session_id'])?'Stripe Checkout session not linked':'Stripe Checkout session linked';
                $reason=(string)($p['last_error']??'none');
                $allowed=['none','creation_unresolved','creation_retry_window_expired','provider_inquiry_unresolved','fulfillment_requires_review','external_refund_unconfirmed','stripe_transport_failure','stripe_authentication_failed','stripe_access_denied','stripe_rate_limited','stripe_provider_unavailable','stripe_invalid_request','stripe_http_failure','stripe_idempotency_conflict','stripe_account_mismatch','stripe_session_validation_failed','stripe_response_invalid','stripe_creation_unresolved'];
                if(!in_array($reason,$allowed,true))$reason='other';
                echo '<section class="commerce-panel" aria-label="Administrator payment diagnostics"><h2>Administrator payment diagnostics</h2><p>Diagnostic version: 2026-11-01-b</p><p>Stage: '.self::e($stage).'</p><p>Purchase state: '.self::e((string)$p['state']).'</p><p>Last failure: '.self::e($reason).'</p><p>Payment recorded: '.((int)$p['captured_minor']>0?'Yes, requires reconciliation':'Not recorded by CTSMD').'</p><p>No Stripe API keys or payment identifiers are displayed. Do not create another purchase while this one is unresolved.</p></section>';
                if($reason==='stripe_account_mismatch'){
                    try{
                        $account=(new CommerceStripeProvider())->accountDiagnostic();
                        echo '<section class="commerce-panel" aria-label="Stripe account comparison"><h2>Stripe account comparison</h2><p>Matches configured account: '.($account['matches']?'Yes':'No').'</p><p>Configured account ends in: '.self::e($account['configured_suffix']).'</p><p>Stripe API account ends in: '.self::e($account['returned_suffix']).'</p><p>Update only the account ID associated with your intended Stripe test key. Never paste API keys here.</p></section>';
                    }catch(Throwable){
                        echo '<p role="status">Stripe account comparison could not be completed. Check the server connection and PHP logs.</p>';
                    }
                }
            }if($p['checkout_url']&&!(int)$p['captured_minor'])echo '<p><a class="button" href="'.self::e($p['checkout_url']).'">Continue payment</a></p>';if(!(int)$p['captured_minor']){self::form('shopping_cancel',['purchase'=>$reference]);echo '<button>Cancel payment</button></form>';}}
        echo '<p><a href="'.self::e(self::url()).'">Continue shopping</a></p>';
    }
