    private static function draft(string $name,string $default=''):string
    {return in_array($_POST['action']??'',['hold','shopping_add','shopping_checkout','shopping_free_checkout'],true)&&isset($_POST[$name])&&is_scalar($_POST[$name])?mb_substr((string)$_POST[$name],0,254):$default;}
    private static function quantityDraft(string $zone,string $category):string
    {$v=$_POST['quantities'][$zone][$category]??'0';return in_array($_POST['action']??'',['hold','shopping_add','shopping_replace'],true)&&is_scalar($v)&&preg_match('/^\d{1,2}$/',(string)$v)?(string)$v:'0';}
