    {echo '<p class="commerce-pricing-terms">Order fee: '.self::money((int)$p['fee_minor'],$p['currency']).'. Tax: '.self::e(number_format((int)$p['tax_basis_points']/100,2)).'% of tickets after discount. Ticket discount: up to '.self::money((int)$p['discount_minor'],$p['currency']).' per order. All charges are included in the total before payment.</p>';}
    private static function deliveryStatus(array $o):void
