    {
        self::catalog();
    }
    private static function extensionCommand(string $action):string{if(CommercePlanningExperience::handles($action))return CommercePlanningExperience::command(self::$db,self::$user,self::$org,$action);throw new RuntimeException('Unknown Commerce action.');}
